package blockbranch.realistic;
import blockbranch.Blockbranch;
import java.nio.file.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;

/** Opt-in focused native fixtures for content iteration and regression recovery. */
public final class FocusedHabitatSmoke {
    public static void register(String habitat){ServerLifecycleEvents.SERVER_STARTED.register(server->{
        try{
            var level=server.overworld();var generator=(RealisticGenerator)level.getChunkSource().getGenerator();
            var result=Path.of(System.getProperty("blockbranch.realisticSmokeResult"));var saved=result.resolveSibling("focused-saved.txt");boolean reload=Files.exists(saved);
            switch(habitat){case "cave_biomes"->{LitCaveSmoke.verify(level,generator,reload);CaveBiomeSmoke.verify(level,generator);}case "section_generation_work"->SectionGenerationWorkSmoke.verify(level,generator);case "column_save_safety"->ColumnSaveSafetySmoke.verify(level,generator,reload);case "lit_review"->LitCaveSmoke.adoptionReview(level,generator);case "lit_cost"->LitCaveSmoke.costOnly(level,generator);case "lit_legacy"->LitCaveSmoke.verifyLegacy(level,generator,reload);case "lit_caves"->LitCaveSmoke.verify(level,generator,reload);case "cave_emitters"->{DripstoneSmoke.verify(level,generator,reload);CaveEmitterSmoke.verify(level);}case "palette_reuse"->{PaletteReuseSmoke.verify(level,generator);DripstoneSmoke.verify(level,generator,reload);}case "dripstone"->DripstoneSmoke.verify(level,generator,reload);case "cave_approach"->CaveApproachSmoke.verify(level,generator,reload);case "underground"->UndergroundSmoke.verify(level,generator,reload);case "underground_legacy"->UndergroundSmoke.verifyLegacyWorld(level,generator);case "world_map"->WorldMapExport.write(level,generator);case "marine_preservation"->{MarineShelfSmoke.verify(level,generator,MarineShelfSmoke.fixture(generator,level.getChunkSource().randomState()),reload);DeepOceanSmoke.verify(level,generator,DeepOceanSmoke.fixture(generator,level.getChunkSource().randomState()),reload);OceanSmoke.verify(level,generator,reload);LukewarmOceanSmoke.verify(level,generator,reload);SeaIceSmoke.verify(level,generator,reload);IcebergSmoke.verify(level,generator,reload);RealisticSpawnSmoke.verify(level,generator,reload);}case "cold_ocean"->LukewarmOceanSmoke.verify(level,generator,reload);case "icebergs"->IcebergSmoke.verify(level,generator,reload);case "eroded_badlands"->BadlandsSmoke.verify(level,generator,reload,3);case "sea_ice"->{SeaIceSmoke.verify(level,generator,reload);FrozenRiverSmoke.verify(level,generator,reload);StonyShoreSmoke.verify(level,generator,reload);CoastalBeachSmoke.verify(level,generator,reload);RiverSmoke.verify(level,generator,reload);RealisticSpawnSmoke.verify(level,generator,reload);}case "stony_shore"->{StonyShoreSmoke.verify(level,generator,reload);CoastalBeachSmoke.verify(level,generator,reload);RiverSmoke.verify(level,generator,reload);RealisticSpawnSmoke.verify(level,generator,reload);}case "warm_dappled"->{WarmDappledSmoke.verify(level,generator,reload);LukewarmOceanSmoke.verify(level,generator,reload);TemperateForestVariantSmoke.verify(level,generator,reload);DarkCherrySmoke.verify(level,generator,reload);RealisticSpawnSmoke.verify(level,generator,reload);}case "surface_predicates"->SurfacePredicateSmoke.verify(level,generator);case "cold_uplands"->{ColdUplandsSmoke.verify(level,generator,reload);MountainPeaksSmoke.verify(level,generator,reload);WindsweptUplandsSmoke.verify(level,generator,reload);OpenSnowSmoke.verify(level,generator,reload,true);RealisticSpawnSmoke.verify(level,generator,reload);}case "spawn"->RealisticSpawnSmoke.verify(level,generator,reload);case "badlands"->{BadlandsSmoke.verify(level,generator,reload);SandyDesertSmoke.verify(level,generator,reload);SavannaUplandsSmoke.verify(level,generator,reload);}case "mountain_peaks"->{MountainPeaksSmoke.verify(level,generator,reload);AlpineScreeSmoke.verify(level,generator,AlpineScreeSmoke.fixture(generator,level.getChunkSource().randomState()),reload);OpenSnowSmoke.verify(level,generator,reload,true);}case "savanna_uplands"->{SavannaUplandsSmoke.verify(level,generator,reload);SavannaSmoke.verify(level,generator,reload);WarmSmoke.verify(level,generator,WarmSmoke.fixture(generator,level.getChunkSource().randomState()),reload);}case "windswept_uplands"->{WindsweptUplandsSmoke.verify(level,generator,reload);ForestSmoke.verify(level,generator,ForestSmoke.fixture(generator,level.getChunkSource().randomState()),reload);TaigaSmoke.verify(level,generator,reload);}case "tropical_variants"->verifyTropical(level,generator,reload);case "dark_cherry"->{DarkCherrySmoke.verify(level,generator,reload);TemperateForestVariantSmoke.verify(level,generator,reload);ForestSmoke.verify(level,generator,ForestSmoke.fixture(generator,level.getChunkSource().randomState()),reload);ForestSmoke.verify(level,generator,ForestSmoke.fixture(generator,level.getChunkSource().randomState(),true),reload,true);}case "flower_forest_assessment"->FlowerForestAssessment.verify(level,generator);case "temperate_variants"->{TemperateForestVariantSmoke.verify(level,generator,reload);ForestSmoke.verify(level,generator,ForestSmoke.fixture(generator,level.getChunkSource().randomState()),reload);ForestSmoke.verify(level,generator,ForestSmoke.fixture(generator,level.getChunkSource().randomState(),true),reload,true);}case "profile_encoding"->ProfileEncodingSmoke.verify(level);case "old_growth_taigas"->{OldGrowthTaigaSmoke.verify(level,generator,reload);TaigaSmoke.verify(level,generator,reload);SnowyTaigaSmoke.verify(level,generator,reload);}case "lukewarm_oceans"->{LukewarmOceanSmoke.verify(level,generator,reload);OceanSmoke.verify(level,generator,reload);DeepOceanSmoke.verify(level,generator,DeepOceanSmoke.fixture(generator,level.getChunkSource().randomState(),true),reload,true);}case "shore"->SandyShoreSmoke.verify(level,generator,SandyShoreSmoke.fixture(generator,level.getChunkSource().randomState()),reload);case "coasts"->CoastalBeachSmoke.verify(level,generator,reload);case "surface_materials"->SurfaceMaterialSmoke.verify(level,generator,reload);case "frozen_river"->FrozenRiverSmoke.verify(level,generator,reload);case "terrain_contours"->{TerrainContourSmoke.verify(level,generator);RiverSmoke.verify(level,generator,reload);RiverChannelSmoke.verify(level,generator,RiverChannelSmoke.fixture(generator,level.getChunkSource().randomState()),reload);}case "broad_river"->{RiverSmoke.verify(level,generator,reload);RiverChannelSmoke.verify(level,generator,RiverChannelSmoke.fixture(generator,level.getChunkSource().randomState()),reload);}case "boundary_tail"->{BoundaryCorrectionSmoke.verify(level,generator);SlopeCorrectionSmoke.verify(level,generator,reload);}case "grove"->{GroveSmoke.verify(level,generator,reload);SnowyTaigaSmoke.verify(level,generator,reload);}case "montane_meadow"->{MontaneMeadowSmoke.verify(level,generator,reload);MeadowSmoke.verify(level,generator,MeadowSmoke.fixture(generator,level.getChunkSource().randomState()),reload);}case "snowy_slopes"->{OpenSnowSmoke.verify(level,generator,reload,true);AlpineScreeSmoke.verify(level,generator,AlpineScreeSmoke.fixture(generator,level.getChunkSource().randomState()),reload);}case "snowy_plains"->{OpenSnowSmoke.verify(level,generator,reload);TundraSmoke.verify(level,generator,TundraSmoke.fixture(generator,level.getChunkSource().randomState()),reload);}case "deep_ocean"->DeepOceanSmoke.verify(level,generator,DeepOceanSmoke.fixture(generator,level.getChunkSource().randomState(),true),reload,true);case "ocean"->OceanSmoke.verify(level,generator,reload);case "snowy_taiga"->SnowyTaigaSmoke.verify(level,generator,reload);case "boreal"->BorealSmoke.verify(level,generator,BorealSmoke.fixture(generator,level.getChunkSource().randomState()),reload);case "slope"->SlopeCorrectionSmoke.verify(level,generator,reload);case "taiga"->TaigaSmoke.verify(level,generator,reload);case "mangrove_swamp"->MangroveSmoke.verify(level,generator,reload);case "litter_cover_codes"->verifyLitterCovers(level,generator,reload);case "swamp"->SwampSmoke.verify(level,generator,SwampSmoke.fixture(generator,level.getChunkSource().randomState()),reload);case "birch_forest"->ForestSmoke.verify(level,generator,ForestSmoke.fixture(generator,level.getChunkSource().randomState(),true),reload,true);case "forest"->ForestSmoke.verify(level,generator,ForestSmoke.fixture(generator,level.getChunkSource().randomState()),reload);case "sunflower"->SunflowerSmoke.verify(level,generator,reload);case "plains"->PlainsSmoke.verify(level,generator,reload);case "jungle"->JungleSmoke.verify(level,generator,reload);case "desert"->SandyDesertSmoke.verify(level,generator,reload);default->throw new IllegalArgumentException("Unknown focused habitat "+habitat);}
            server.saveEverything(false,true,true);Files.writeString(saved,"saved\n");Files.writeString(result,"PASS\n");
            Blockbranch.LOGGER.info("FOCUSED_HABITAT_NATIVE_PASS habitat={} mode={}",habitat,reload?"RELOAD":"NEW");
        }catch(Throwable error){Blockbranch.LOGGER.error("FOCUSED_HABITAT_NATIVE_FAIL",error);}finally{server.halt(false);}
    });}
    private static void verifyTropical(net.minecraft.server.level.ServerLevel level,RealisticGenerator generator,boolean reload){
        var random=level.getChunkSource().randomState();
        TropicalForestSmoke.verify(level,generator,reload);
        JungleSmoke.verify(level,generator,reload);
        SavannaSmoke.verify(level,generator,reload);
        WarmSmoke.verify(level,generator,WarmSmoke.fixture(generator,random),reload);
        HumidSmoke.verify(level,generator,HumidSmoke.fixture(generator,random),reload);
    }
    /** Ground-cover smokes whose witnesses read variant-normalised litter codes, without the tropical-forest witnesses. WarmSmoke and WoodlandSmoke are omitted: their fixtures currently lie in coastal winter-rain oak woodland, so their biome assertions fail before any litter witness. */
    private static void verifyLitterCovers(net.minecraft.server.level.ServerLevel level,RealisticGenerator generator,boolean reload){
        var random=level.getChunkSource().randomState();
        JungleSmoke.verify(level,generator,reload);
        SavannaSmoke.verify(level,generator,reload);
        var humid=HumidSmoke.fixture(generator,random);
        for(int dz=-3;dz<=3;dz++)for(int dx=-3;dx<=3;dx++)level.getChunk((humid.getX()>>4)+dx,(humid.getZ()>>4)+dz);
        HumidSmoke.verify(level,generator,humid,reload);
    }
    private FocusedHabitatSmoke(){}
}
